"use client";
import * as React from "react";
import { Dialog as BaseDialog } from "@base-ui-components/react/dialog";
import { cn } from "@/lib/utils";

// shadcn-style Dialog on the Base UI primitive. Backdrop and popup use theme tokens.
export const Dialog = BaseDialog.Root;
export const DialogTrigger = BaseDialog.Trigger;
export const DialogClose = BaseDialog.Close;

// `container` lets a caller mount the popup inside a themed subtree (portals default
// to <body>, which sits outside a container that is previewing a theme).
export function DialogContent({
  className,
  children,
  container,
  ...props
}: React.ComponentProps<typeof BaseDialog.Popup> & {
  container?: React.ComponentProps<typeof BaseDialog.Portal>["container"];
}) {
  return (
    <BaseDialog.Portal container={container}>
      <BaseDialog.Backdrop className="fixed inset-0 bg-foreground/25" />
      <BaseDialog.Popup
        className={cn(
          "fixed left-1/2 top-1/2 w-[min(28rem,calc(100vw-2rem))] -translate-x-1/2 -translate-y-1/2",
          "rounded-[var(--radius-card)] border border-border bg-background p-5 shadow-xl",
          "focus-visible:outline-none",
          className
        )}
        {...props}
      >
        {children}
      </BaseDialog.Popup>
    </BaseDialog.Portal>
  );
}

export function DialogTitle({ className, ...props }: React.ComponentProps<typeof BaseDialog.Title>) {
  return <BaseDialog.Title className={cn("text-base font-semibold text-foreground", className)} {...props} />;
}

export function DialogDescription({ className, ...props }: React.ComponentProps<typeof BaseDialog.Description>) {
  return <BaseDialog.Description className={cn("mt-1 text-sm text-muted-foreground", className)} {...props} />;
}
